#include "club/ClubUi.h"
#include "networking/NetworkRoom.h"
#include "cards/CardCatalog.h"
#include <chrono>
#include <iostream>
#include <numeric>
#include <stdexcept>
#include <thread>
namespace {
using namespace fl;using namespace fl::net;
void check(bool v,const char* text){if(!v)throw std::runtime_error(text);}
ClubCommand command(ClubOp op){ClubCommand c;c.op=op;c.request=newRequestId();return c;}
unsigned copies(const ClubProfile& p){return std::accumulate(p.owned.begin(),p.owned.end(),0U);}
void storage(const std::filesystem::path& path){const auto defs=unlimitedDefinitions();std::vector<std::uint16_t> opened;auto pack=command(ClubOp::Pack);std::vector<std::uint16_t> first;Face scribble=defaultFace();scribble[256*30+90]=3;
    {ClubStore store(path,defs);store.ensure("alice",0);store.ensure("bob",1);check(store.profile("alice").cents==50000&&copies(store.profile("alice"))==60,"Starter inventory");store.apply("alice",pack,opened);first=opened;check(opened.size()==15&&copies(store.profile("alice"))==75&&store.profile("alice").cents==40000,"Pack debit/credit");int c=0,u=0,r=0;for(auto d:opened){if(defs[d].rarity=="common")++c;if(defs[d].rarity=="uncommon")++u;if(defs[d].rarity=="rare")++r;check(!defs[d].basicLand,"Basic land replaced rare slot");}check(c==11&&u==3&&r==1,"Pack rarity counts");store.apply("alice",pack,opened);check(opened==first&&copies(store.profile("alice"))==75&&store.profile("alice").cents==40000,"Duplicate purchase");
    auto land=command(ClubOp::Land);for(std::size_t i=0;i<defs.size();++i)if(defs[i].basicLand){land.value=static_cast<int>(i);break;}store.apply("alice",land,opened);check(copies(store.profile("alice"))==76&&store.profile("alice").cents==39999,"Land cent");
    auto deck=command(ClubOp::SaveDeck);deck.name="Test";deck.cards=store.profile("alice").decks.front().cards;const auto before=copies(store.profile("alice"));store.apply("alice",deck,opened);check(store.profile("alice").decks.size()==2&&copies(store.profile("alice"))==before,"Deck consumed copies");auto bad=command(ClubOp::SaveDeck);bad.name="Cheat";bad.cards.assign(120,0);check(store.apply("alice",bad,opened)=="DECK EXCEEDS OWNED COPIES","Unowned deck allowed");auto select=command(ClubOp::SelectDeck);select.name="Test";store.apply("alice",select,opened);check(store.profile("alice").selected=="Test","Selection not saved");auto face=command(ClubOp::Face);face.face=scribble;store.apply("alice",face,opened);check(store.face("alice")==scribble,"Face save");face.request=newRequestId();face.face[0]=18;check(store.apply("alice",face,opened)=="INVALID FACE"&&store.face("alice")==scribble,"Invalid face accepted");check(copies(store.profile("bob"))==60&&store.profile("bob").cents==50000,"Player inventory mixed");check(store.backup(path.parent_path()/"test-backup.sqlite3"),"Backup failed");}
    {ClubStore store(path,defs);store.ensure("alice",0);check(store.profile("alice").selected=="Test"&&store.face("alice")==scribble,"Restart lost profile");store.apply("alice",pack,opened);check(opened==first&&copies(store.profile("alice"))==76,"Restart replay duplicated pack");for(int i=0;i<5;++i)store.apply("alice",command(ClubOp::Pack),opened);check(store.profile("alice").cents==9999,"Insufficient balance changed money");}
}
void protocols(){auto c=command(ClubOp::Face);c.face=defaultFace();auto bytes=encodeClubCommand(c);auto d=decodeClubCommand(bytes);check(d&&d->face==c.face,"Face wire round trip");for(auto n:{0U,3U,20U,100U,65535U})check(!decodeClubCommand(std::span(bytes.data(),n)),"Truncated command accepted");auto bad=bytes;bad.push_back(0);check(!decodeClubCommand(bad),"Trailing club payload accepted");ClubView v;v.profile.owned.resize(302);v.profile.cents=50000;v.profile.selected="Starter";v.profile.decks.push_back({"Starter",{1,2,3}});auto b=encodeClubView(v);check(decodeClubView(b).has_value(),"Club view round trip");for(std::size_t n=0;n<b.size();++n)check(!decodeClubView({b.data(),n}),"Truncated club view accepted");}
void painter(){ClubView v;v.profile.owned.resize(302);ClubUi ui;ui.viewport(1280,720);ui.show(ClubPage::Face,v);const auto original=ui.canvas;ui.click(100,220,v,unlimitedDefinitions(),0);ui.move(160,280);ui.up();check(ui.canvas!=original,"Pencil did not draw");ui.undoPaint(false);check(ui.canvas==original,"Undo failed");ui.undoPaint(true);check(ui.canvas!=original,"Redo failed");auto painted=ui.canvas;ui.action(55,v,unlimitedDefinitions(),0);check(std::all_of(ui.canvas.begin(),ui.canvas.end(),[](auto n){return n==0;}),"Clear failed");ui.undoPaint(false);check(ui.canvas==painted,"Clear undo");bool sent=false;ui.send=[&](ClubCommand c){sent=c.op==ClubOp::Face&&c.face==painted;};ui.action(56,v,unlimitedDefinitions(),0);check(sent,"Painter did not submit save");ui.close();ui.show(ClubPage::Face,v);ui.ink=8;ui.action(57,v,unlimitedDefinitions(),0);ui.click(40,164,v,unlimitedDefinitions(),0);check(ui.canvas[0]==8&&ui.canvas[90*256+80]==1,"Bucket fill crossed boundary");ui.undoPaint(false);check(ui.canvas==v.faces[0],"Bucket undo failed");}
void pump(NetworkRoom& host,NetworkRoom& guest,int count){for(int i=0;i<count;++i){host.update(0.01F);guest.update(0.01F);std::this_thread::sleep_for(std::chrono::milliseconds(1));}}
void multiplayer(const std::filesystem::path& path){NetworkRoom host,guest;host.configureClub(path,"11111111111111111111111111111111");guest.configureClub({},"22222222222222222222222222222222");unsigned short port=35745;while(port<35765&&!host.host(port))++port;check(port<35765,"Cannot host");check(guest.join("127.0.0.1",port),"Cannot join");pump(host,guest,200);check(guest.ready()&&guest.club().profile.cents==50000,"Guest profile missing");auto pack=command(ClubOp::Pack);guest.clubCommand(pack);pump(host,guest,40);check(copies(guest.club().profile)==75&&guest.club().profile.cents==40000,"Network pack failed");guest.clubCommand(pack);pump(host,guest,30);check(copies(guest.club().profile)==75,"Network replay credited twice");auto face=command(ClubOp::Face);face.face=defaultFace();face.face[256*30+120]=9;guest.clubCommand(face);pump(host,guest,200);check(host.club().faces[1]==face.face&&guest.club().faces[1]==face.face,"Saved face not shared");
    auto save=command(ClubOp::SaveDeck);save.name="Tiny";save.cards.assign(guest.club().profile.decks.front().cards.begin(),guest.club().profile.decks.front().cards.begin()+10);guest.clubCommand(save);pump(host,guest,30);auto use=command(ClubOp::SelectDeck);use.name="Tiny";guest.clubCommand(use);pump(host,guest,30);check(guest.club().profile.selected=="Tiny","Guest deck selection missing");host.clubCommand(command(ClubOp::Ready));guest.clubCommand(command(ClubOp::Ready));pump(host,guest,50);Tabletop h,g;host.syncTable(h);guest.syncTable(g);check(host.club().match.active&&guest.club().match.active&&h.cards().size()==70&&g.cards().size()==70,"Selected decks not loaded");check(h.hand(0).size()==7&&g.hand(1).size()==7,"Private opening hand missing");for(auto id:g.hand(0))check(g.card(id)->definition==hiddenDefinition,"Opening hand leaked");guest.clubCommand(command(ClubOp::Life));pump(host,guest,20);auto life=command(ClubOp::Life);life.value=-1;guest.clubCommand(life);pump(host,guest,20);check(host.club().match.life[1]==19,"Life sync failed");auto win=command(ClubOp::Winner);win.value=1;host.clubCommand(win);guest.clubCommand(command(ClubOp::Winner));pump(host,guest,30);check(host.club().match.active,"Mismatched winner ended match");guest.clubCommand(win);pump(host,guest,20);check(!host.club().match.active&&guest.club().match.winner==1,"Agreed result not resolved");host.clubCommand(command(ClubOp::Ready));guest.clubCommand(command(ClubOp::Ready));pump(host,guest,30);host.clubCommand(command(ClubOp::Reset));guest.clubCommand(command(ClubOp::Reset));pump(host,guest,30);host.syncTable(h);guest.syncTable(g);check(!host.club().match.active&&h.hand(0).empty()&&g.hand(1).empty(),"Dual reset left old hands");guest.reconnect();pump(host,guest,200);check(copies(guest.club().profile)==75&&guest.club().faces[1]==face.face,"Reconnect lost club profile");host.stop();guest.stop();check(host.host(port),"Host restart failed");check(guest.join("127.0.0.1",port),"Join after host restart failed");pump(host,guest,200);check(guest.club().profile.cents==40000&&guest.club().profile.selected=="Tiny"&&guest.club().faces[1]==face.face,"Host restart lost guest profile");host.stop();guest.stop();}
}
int main(){try{const auto path=std::filesystem::temp_directory_path()/("club-phase4-"+newRequestId());std::filesystem::create_directories(path);storage(path/"store.sqlite3");protocols();painter();multiplayer(path/"host.sqlite3");std::filesystem::remove_all(path);std::cout<<"PASS: SQLite persistence/backup, pack rarity/debit/copy IDs, exactly-once retries/restarts, owned-only decks, face validation/painter undo, bounded protocol, actual UDP shop/decks/faces/match/life/result/reconnect\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
